export function showDownloadToast(filename) {
  try {
    let container = document.getElementById('toast-container');
    if (!container) {
      container = document.createElement('div');
      container.id = 'toast-container';
      document.body.appendChild(container);
    }
    const toast = document.createElement('div');
    toast.className = 'toast success';
    toast.style.cssText = 'display: flex; align-items: center; gap: 12px; background: #0f172a; color: white; border-left: 4px solid #10b981; padding: 14px 20px; border-radius: 6px; box-shadow: 0 10px 25px rgba(0,0,0,0.4); margin-top: 10px; z-index: 999999; animation: slideIn 0.3s ease;';
    toast.innerHTML = `
      <div style="font-size: 24px;">📥</div>
      <div>
        <div style="font-weight: 700; font-size: 14px; color: #10b981;">Document Download Initiated</div>
        <div style="font-size: 12px; color: #cbd5e1; max-width: 320px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${filename}</div>
      </div>
    `;
    container.appendChild(toast);
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.4s ease';
      setTimeout(() => {
        if (toast.parentNode) toast.parentNode.removeChild(toast);
      }, 400);
    }, 4000);
  } catch (e) {
    console.log('Download initiated:', filename);
  }
}

/**
 * Trigger browser file download via Blob with delayed revocation & backend fallback
 */
export function triggerDownload(filename, content, mimeType = 'text/html;charset=utf-8') {
  showDownloadToast(filename);

  try {
    const blob = new Blob(['\ufeff', content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    if (a.style) a.style.display = 'none';
    a.href = url;
    a.download = filename;
    a.setAttribute('download', filename);
    a.target = '_blank';
    a.rel = 'noopener';
    document.body.appendChild(a);

    // Mouse click event
    if (typeof MouseEvent !== 'undefined') {
      const clickEvt = new MouseEvent('click', {
        bubbles: true,
        cancelable: true,
        view: window
      });
      a.dispatchEvent(clickEvt);
    } else {
      a.click();
    }

    // Delay revocation by 2 minutes so browser download manager has time to complete
    setTimeout(() => {
      try {
        if (a.parentNode) {
          a.parentNode.removeChild(a);
        }
        URL.revokeObjectURL(url);
      } catch (e) {}
    }, 120000);
  } catch (err) {
    console.warn('Direct Blob download failed, attempting backend download route:', err);
    // Fallback via server attachment endpoint
    fetch('/api/download', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ filename, content, mimeType })
    })
    .then(res => res.blob())
    .then(blob => {
      const u = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = u;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      setTimeout(() => {
        if (link.parentNode) link.parentNode.removeChild(link);
        URL.revokeObjectURL(u);
      }, 60000);
    })
    .catch(() => {
      // Ultimate fallback: open in new tab
      const win = window.open('', '_blank');
      if (win) {
        win.document.open();
        win.document.write(content);
        win.document.close();
      }
    });
  }
}

export function formatAdobeDate(dateInput) {
  const pad = (n) => String(n).padStart(2, '0');
  
  if (!dateInput) {
    const d = new Date();
    return `${d.getFullYear()}.${pad(d.getMonth() + 1)}.${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())} +05'30'`;
  }

  if (typeof dateInput === 'string') {
    const trimmed = dateInput.trim();
    // If it's already in the exact format "YYYY.MM.DD HH:mm:ss +05'30'"
    if (/^\d{4}\.\d{2}\.\d{2} \d{2}:\d{2}:\d{2} \+05'30'$/.test(trimmed)) {
      return trimmed;
    }
    // If it's "YYYY.MM.DD HH:mm:ss"
    if (/^\d{4}\.\d{2}\.\d{2} \d{2}:\d{2}:\d{2}$/.test(trimmed)) {
      return `${trimmed} +05'30'`;
    }
    // If it has "YYYY.MM.DD"
    const dotParts = trimmed.split(' ');
    if (/^\d{4}\.\d{2}\.\d{2}$/.test(dotParts[0])) {
      const timePart = dotParts[1] || '11:30:00';
      return `${dotParts[0]} ${timePart} +05'30'`;
    }
    // Check if DD.MM.YYYY or DD-MM-YYYY
    const ddmmyyyy = trimmed.split(' ');
    const parts = ddmmyyyy[0].split(/[.\-/]/);
    if (parts.length === 3) {
      let y, m, dNum;
      if (parts[0].length === 4) {
        y = parts[0];
        m = pad(parts[1]);
        dNum = pad(parts[2]);
      } else {
        dNum = pad(parts[0]);
        m = pad(parts[1]);
        y = parts[2];
      }
      const timePart = ddmmyyyy[1] || '11:45:20';
      return `${y}.${m}.${dNum} ${timePart} +05'30'`;
    }
  }

  const d = (dateInput instanceof Date) ? dateInput : new Date(dateInput);
  if (!isNaN(d.getTime())) {
    return `${d.getFullYear()}.${pad(d.getMonth() + 1)}.${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())} +05'30'`;
  }

  const now = new Date();
  return `${now.getFullYear()}.${pad(now.getMonth() + 1)}.${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())} +05'30'`;
}

export function generateAdobeDigitalSignature(name, designation, reason = 'Official Record Verification', location = 'New Delhi, India', dateOrOptions = null) {
  const currentPersonnel = (typeof window !== 'undefined' && window.ehrmsState?.currentUser?.name) 
    ? window.ehrmsState.currentUser.name 
    : 'ANURAG ANIL BAWASKAR';

  const signerName = (name || currentPersonnel).toUpperCase().replace(/SHRI|SMT\.|DR\./g, '').trim();
  
  let rawDate = null;
  if (typeof dateOrOptions === 'string' || dateOrOptions instanceof Date) {
    rawDate = dateOrOptions;
  } else if (dateOrOptions && typeof dateOrOptions === 'object') {
    rawDate = dateOrOptions.date || dateOrOptions.signDate || dateOrOptions.timestamp || null;
    if (dateOrOptions.reason) reason = dateOrOptions.reason;
    if (dateOrOptions.location) location = dateOrOptions.location;
  }

  const dateFormatted = formatAdobeDate(rawDate);

  return `
    <div class="adobe-digital-signature" style="
      display: inline-flex;
      align-items: center;
      gap: 14px;
      border: 1px solid #555555;
      background-color: #ffffff;
      padding: 9px 15px;
      font-family: Arial, Helvetica, sans-serif;
      text-align: left;
      box-sizing: border-box;
      margin: 8px 0;
      width: 385px;
      max-width: 100%;
    ">
      <!-- Iconic Adobe Green Tickmark -->
      <div style="flex-shrink: 0; display: flex; align-items: center; justify-content: center;">
        <svg width="46" height="46" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M9 24.5L19.5 35L39 13" stroke="#008000" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </div>
      <!-- Exact Adobe Signature Properties -->
      <div style="font-size: 11px; line-height: 1.48; color: #000000;">
        <div style="font-size: 13.5px; font-weight: bold; color: #008000; margin-bottom: 2px; letter-spacing: 0.2px;">Signature Valid</div>
        <div style="font-size: 11px; color: #000000;">Digitally signed by <strong>${signerName}</strong></div>
        <div style="font-size: 10px; color: #222222;">Date: ${dateFormatted}</div>
        <div style="font-size: 10px; color: #222222;">Reason: ${reason}</div>
        <div style="font-size: 10px; color: #222222;">Location: ${location}</div>
      </div>
    </div>
  `;
}

